                createdAt: run.created_at || run.createdAt || '',
                startedAt: run.run_started_at || run.runStartedAt || '',
                updatedAt: run.updated_at || run.updatedAt || '',
                day: isoDay(run.created_at || run.createdAt || run.run_started_at || run.runStartedAt),
